from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class NrhoifParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        self.set_parameter('a3MeasEnabled', 'rsrp')
        self.set_struct_parameter('a3MeasSsbRsrp', [
            {
                'a3HysteresisSsbRsrp': '1',
                'a3OffsetSsbRsrp': '4',
                'a3TimeToTriggerSsbRsrp': 'ms40',
            }
        ])
        self.set_parameter('a5MeasEnabled', 'rsrp')
        self.set_struct_parameter('a5MeasSsbRsrp', [
            {
                'a5HysteresisSsbRsrp': '0',
                'a5Threshold1SsbRsrp': '46',
                'a5Threshold2SsbRsrp': '56',
                'a5TimeToTriggerSsbRsrp': 'ms0',
            }
        ])
        self.set_parameter('cellDepType', 'SA')
        if execution_config['release'] < 25.3:
            self.set_parameter('chBw', '50MHz')
        self.set_parameter('freqBandIndicatorNR', '76')
        self.set_parameter('ifhoSsbScs', '30 KHz')
        self.set_parameter('ifhoSsbSmtcDuration', 'sf1')
        self.set_parameter('ifhoSsbSmtcPeriodicity', 'sf20')
        self.set_parameter('ssbFrequency', '66000')
